// On this day: what happened on today's date in other years, from
// Wikipedia's "On this day" feed in the language picked in the settings. One
// event at a time in big type, with its year and how long ago that was, and
// its page's picture where the screen has room and color. Each render shows
// the next one (every hour by default); a tap, a swipe, the frame's next and
// previous keys or the arrow keys move along too. At midnight it starts over
// with the new day's events.
//
// The day's events are kept in the scene's state (the private `onThisDay`
// field): fetched once a day, and still shown, with a note, when the next
// day's do not come.
import type { Happening } from './otd'
import { LANGUAGES, agoWords, dateWords, dayOf, fetchDay, HEADERS, wordsFor, yearWords } from './otd'

type Day = {
  key: string // the language and the day the events are for: "en:2026-11-28"
  date: string
  lang: string
  events: Happening[]
  index: number // the event showing
  shownAt: number // since when
  lookedAt: number // the last time the feed was asked, and for which key
  lookedKey: string
  error: string
}

// After a failed look, the next one no sooner than this.
export const RETRY_MS = 30 * 60 * 1000

const EMPTY: Day = { key: '', date: '', lang: '', events: [], index: 0, shownAt: 0, lookedAt: 0, lookedKey: '', error: '' }

/** The state's record: an object, or its JSON from a saved field. */
export function readDay(value: any): Day {
  let v = value
  if (typeof v === 'string') {
    try {
      v = JSON.parse(v)
    } catch (e) {
      v = null
    }
  }
  if (!v || typeof v !== 'object') return { ...EMPTY }
  return {
    ...EMPTY,
    ...v,
    events: Array.isArray(v.events) ? v.events : [],
    index: Number(v.index) || 0,
    shownAt: Number(v.shownAt) || 0,
    lookedAt: Number(v.lookedAt) || 0,
  }
}

/** The record after this render: the day's events fetched when the day (or
 * the language) changed, and the next event once the one showing has had its
 * turn (most of the scene's interval: a tap's render or a layout's clock does
 * not move it on). */
export function update(day: Day, lang: string, now: number, interval: number, embedded: boolean): Day {
  const date = dayOf(new Date(now))
  const key = `${lang}:${date}`
  if (day.key !== key && !(day.lookedKey === key && now - day.lookedAt < RETRY_MS && now >= day.lookedAt)) {
    try {
      const events = fetchDay(lang, date, embedded)
      return { key, date, lang, events, index: 0, shownAt: now, lookedAt: now, lookedKey: key, error: '' }
    } catch (e) {
      day = { ...day, lookedAt: now, lookedKey: key, error: String(e?.message || e) }
    }
  }
  const n = day.events.length
  if (n > 1 && now - day.shownAt >= interval * 800) return { ...day, index: (day.index + 1) % n, shownAt: now }
  return day
}

/** Seconds until the next render the scene needs: the next event's turn,
 * midnight's new day, or a retry, at most the interval. */
export function secondsToNext(day: Day, lang: string, now: number, interval: number): number {
  const d = new Date(now)
  const midnight = new Date(d.getFullYear(), d.getMonth(), d.getDate() + 1, 0, 0, 5).getTime()
  let next = Math.min(midnight, now + interval * 1000)
  if (day.key !== `${lang}:${dayOf(d)}`) next = Math.min(next, Math.max(day.lookedAt + RETRY_MS, now + 60 * 1000))
  return Math.max(1, Math.ceil((next - now) / 1000))
}

// ------------------------------------------------------------ moving along

// The record the last render drew, for the handlers.
let drawn: Day = { ...EMPTY }

function step(day: Day, by: number) {
  const n = day.events.length
  if (n < 2) return false
  drawn = { ...day, index: (((day.index + by) % n) + n) % n, shownAt: Date.now() }
  frameos.setState('onThisDay', drawn)
  return true
}

const KEYS: Record<string, number> = { ArrowRight: 1, ArrowDown: 1, PageDown: 1, ' ': 1, ArrowLeft: -1, ArrowUp: -1, PageUp: -1 }

// The frame's next and previous keys (and a swipe in from the screen's edge)
// come as forward and back; a keyboard's arrows as keyDown.
export function onEvent(app: FrameOSApp, context: FrameOSContext) {
  const day = readDay(app.state.onThisDay)
  if (context.event === 'forward') return step(day, 1)
  if (context.event === 'back') return step(day, -1)
  if (context.event === 'keyDown') {
    const by = KEYS[String(context.payload?.key ?? '')]
    return by ? step(day, by) : false
  }
  return false
}

// ------------------------------------------------------------ the picture

// The event's picture, kept while the interpreter lives (a tap draws it again
// without a download), and let go for the next one.
let kept: { key: string; ref: any } | null = null

// Wikipedia makes thumbnails at a few widths only (330, 500 and 960 among
// them; others are refused): the smallest that is wide enough, never wider
// than the picture itself.
export function thumbUrl(thumb: { src: string; w: number; ow?: number }, need: number): string {
  const m = /^(.*\/thumb\/.*\/)(\d+)px-([^/]+)$/.exec(thumb.src)
  if (!m) return thumb.src
  const widths = [330, 500, 960].filter((w) => !thumb.ow || w <= thumb.ow)
  if (!widths.length) return thumb.src
  const width = widths.find((w) => w >= need * 0.9) ?? widths[widths.length - 1]
  return `${m[1]}${width}px-${m[3]}`
}

function picture(app: FrameOSApp, thumb: any, w: number, h: number) {
  const scale = app.frame.scale || 1
  // As many pixels as the box has on the panel, fewer on an ESP32 in color,
  // which keeps a picture in two bytes a pixel beside its canvas.
  const most = !app.frame.embedded ? 4000000 : app.frame.color === false ? 1400000 : 400000
  let pw = w * scale
  let ph = h * scale
  const room = Math.sqrt(most / Math.max(1, pw * ph)) * 0.999
  if (room < 1) {
    pw *= room
    ph *= room
  }
  pw = Math.max(1, Math.round(pw))
  ph = Math.max(1, Math.round(ph))
  // The thumbnail's width that covers the box, from its shape.
  const aspect = thumb.w > 0 && thumb.h > 0 ? thumb.w / thumb.h : 1
  const url = thumbUrl(thumb, Math.max(pw, ph * aspect))
  const key = `${url}|${pw}x${ph}`
  if (kept && kept.key === key) return kept.ref
  if (kept) {
    frameos.releaseImage(kept.ref)
    kept = null
  }
  const r = frameos.fetchImage(url, { keep: true, width: pw, height: ph, fit: 'cover', headers: { 'User-Agent': HEADERS['User-Agent'] } })
  if (!r.image) {
    frameos.log(`On this day: the picture did not load: ${r.error || 'no picture'}`)
    return null
  }
  kept = { key, ref: r.image }
  return r.image
}

// ------------------------------------------------------------ drawing

// High contrast where the panel shows no color (black and white, greys), or
// when the Contrast setting asks for it; solid inks on color e-paper.
const THEMES: Record<string, Record<string, string>> = {
  color: {
    page: 'bg-[#f6f1e7] text-[#1f2430]',
    soft: 'text-[#6d6a63]',
    accent: 'text-[#b4552d]',
    rule: 'bg-[#ddd3c1]',
    photo: 'bg-[#e9e1d0]',
    note: 'bg-[#7f1d1d] text-white',
  },
  high: {
    page: 'bg-white text-black',
    soft: 'text-black',
    accent: 'text-black',
    rule: 'bg-black',
    photo: 'bg-white',
    note: 'bg-white text-black border-2 border-black',
  },
}
THEMES.inks = { ...THEMES.high, accent: 'text-[#6b1119]', note: 'bg-[#6b1119] text-white' }

function themeOf(app: FrameOSApp) {
  const mode = String(app.state.contrast || 'auto')
  if (mode === 'high' || (mode === 'auto' && app.frame.color === false)) return { t: THEMES.high, name: 'high' }
  if (mode === 'auto' && app.frame.paper === true) return { t: THEMES.inks, name: 'inks' }
  return { t: THEMES.color, name: 'color' }
}

// The size of everything: 1 on an 800x480 panel, less on a small one, by
// halves more where a big panel is drawn at its own pixels.
function unitOf(W: number, H: number) {
  const short = Math.min(W, H)
  if (short >= 900) return Math.min(3, Math.floor((short / 480) * 2) / 2)
  return Math.max(0.6, Math.min(1, short / 480))
}

// A text in the largest of `sizes` that fits w x h; the smallest, cut to the
// lines that fit, when none does.
function fitting(text: string, w: number, h: number, sizes: number[], extra = '') {
  for (const size of sizes) {
    const lead = Math.round(size * 1.25)
    const tall = frameos.measureText([text], { className: `text-[${size}px] leading-[${lead}px] ${extra}`, width: Math.max(1, Math.floor(w)) })[0]
    if (tall <= h) return { size, lead, lines: Math.max(1, Math.round(tall / lead)), fits: true }
  }
  const size = sizes[sizes.length - 1]
  const lead = Math.round(size * 1.25)
  return { size, lead, lines: Math.max(1, Math.floor(h / lead)), fits: false }
}

// The calendar page of the scene's icon, for the screen with nothing to show.
const ICON = 'M7,10H12V15H7M19,19H5V8H19M19,3H18V1H16V3H8V1H6V3H5C3.89,3 3,3.9 3,5V19A2,2 0 0,0 5,21H19A2,2 0 0,0 21,19V5A2,2 0 0,0 19,3Z'

function Empty({ W, H, u, t, title, error }: any) {
  const icon = Math.round(Math.max(40, Math.min(110, Math.min(W, H) * 0.18)))
  const big = Math.max(18, Math.round(32 * u))
  const line = Math.max(12, Math.round(17 * u))
  const room = Math.round(Math.min(W, H) <= 500 && Math.abs(W - H) < 8 ? Math.min(W, H) * 0.72 : Math.min(W - 48 * u, 560 * u))
  return (
    <div className={`flex flex-col items-center justify-center w-[${W}px] h-[${H}px] ${t.page}`}>
      <svg className={`w-[${icon}px] h-[${icon}px] ${t.accent}`} viewBox="0 0 24 24">
        <path fill="currentColor" d={ICON} />
      </svg>
      <div className={`font-[Cormorant_Garamond] font-bold text-[${big}px] leading-tight text-center mt-[${Math.round(10 * u)}px] w-[${room}px]`}>{title}</div>
      <div className={`text-[${line}px] leading-snug text-center mt-[${Math.round(8 * u)}px] w-[${room}px] line-clamp-4 ${t.soft}`}>
        {error ? `Could not get the day's events: ${error}.` : 'Looking for what happened on this day.'}
      </div>
      {error ? <div className={`text-[${line}px] leading-snug text-center mt-[${Math.round(6 * u)}px] w-[${room}px] ${t.soft}`}>Trying again in half an hour.</div> : null}
    </div>
  )
}

export function get(app: FrameOSApp, context: FrameOSContext) {
  const W = context?.imageWidth ?? app.frame.width
  const H = context?.imageHeight ?? app.frame.height
  const round = context?.round === true
  const now = Date.now()
  const lang = LANGUAGES.includes(String(app.state.language)) ? String(app.state.language) : 'en'
  const words = wordsFor(lang)
  const interval = Number(app.state.refreshInterval) || 3600
  const { t, name } = themeOf(app)
  const u = unitOf(W, H)

  const before = readDay(app.state.onThisDay)
  const day = update(before, lang, now, interval, app.frame.embedded === true)
  if (JSON.stringify(day) !== JSON.stringify(before)) frameos.setState('onThisDay', day)
  drawn = day
  const wait = secondsToNext(day, lang, now, interval)
  if (wait < interval) frameos.setNextSleep(wait)

  const n = day.events.length
  if (!n) return <Empty W={W} H={H} u={u} t={t} title={words.title} error={day.error} />
  const index = ((day.index % n) + n) % n
  const e = day.events[index]
  const today = dayOf(new Date(now))
  // A day kept from before, when today's did not come: it says so.
  const stale = day.date !== today || day.lang !== lang
  const note = stale && day.error ? `Could not get today's events: ${day.error}. These are from ${dateWords(day.lang, day.date)}.` : ''

  const short = Math.min(W, H)
  const pad = Math.round(Math.max(12, 28 * u))
  const head = Math.max(11, Math.round(15 * u))
  const headLead = Math.round(head * 1.4)
  const yearSize = Math.max(34, Math.round(84 * u))
  const agoSize = Math.max(13, Math.round(19 * u))
  const gap = Math.round(Math.max(8, 16 * u))
  const header = `${words.title} · ${dateWords(day.lang || lang, day.date || today)}`
  const counter = `${index + 1} / ${n}`

  // Its picture: where the screen has color and room, and the event has one.
  // Without it, "(pictured)" points at nothing.
  const pictures = String(app.state.pictures ?? 'true') !== 'false'
  const wide = W >= H * 1.15
  const photoOn = pictures && !!e.thumb && !round && short >= 360 && name !== 'high'
  const unpictured = (s: string) => s.replace(/\s*\((?:pictured|shown|illustrated|left|right|center)[^)]*\)/gi, '')

  const toNext = () => step(drawn, 1)
  const swiped = (ev: FrameOSUiEvent) => (ev.direction === 'left' ? step(drawn, 1) : ev.direction === 'right' ? step(drawn, -1) : false)

  if (round) {
    // The date in the arc at the top, the year and the event in the square
    // inside the circle, where in the day's list at the bottom.
    const side = Math.floor((short / 2 - 12) * Math.SQRT2)
    const top = Math.round((H - side) / 2)
    const left = Math.round((W - side) / 2)
    const year = Math.round(Math.min(yearSize, side * 0.22))
    const room = side - Math.round(year * 1.05) - Math.round(agoSize * 1.4) - gap
    const body = fitting(unpictured(e.text), side, room, [30, 28, 26, 24, 22, 20, 18, 17, 16, 15, 14].map((s) => Math.max(13, Math.round(s * u))), 'text-center')
    return (
      <div className={`relative w-[${W}px] h-[${H}px] ${t.page}`} onClick={toNext} onSwipe={swiped}>
        <div className={`absolute left-0 top-[${Math.round(top * 0.45)}px] w-[${W}px] text-center text-[${head}px] leading-[${headLead}px] uppercase font-bold ${t.accent}`}>{header}</div>
        <div className={`absolute left-[${left}px] top-[${top}px] w-[${side}px] h-[${side}px] flex flex-col items-center justify-center text-center`}>
          <div className={`font-[Cormorant_Garamond] font-bold text-[${year}px] leading-none ${t.accent}`}>{yearWords(day.lang, e.year)}</div>
          <div className={`text-[${agoSize}px] leading-[${Math.round(agoSize * 1.4)}px] ${t.soft}`}>{agoWords(day.lang, e.year, new Date(now))}</div>
          <div className={`mt-[${gap}px] w-[${side}px] text-[${body.size}px] leading-[${body.lead}px] line-clamp-${body.lines}`}>{unpictured(e.text)}</div>
        </div>
        <div className={`absolute left-0 bottom-[${Math.round(top * 0.4)}px] w-[${W}px] text-center text-[${head}px] leading-[${headLead}px] ${t.soft}`}>{note ? note.slice(0, 60) : counter}</div>
      </div>
    )
  }

  // The rest: the header along the top, the picture beside the words (wide)
  // or above them (tall), the source along the bottom.
  const innerW = W - pad * 2
  const innerH = H - pad * 2
  const foot = Math.max(11, Math.round(13 * u))
  const footLead = Math.round(foot * 1.4)
  const noteLines = note ? 2 : 0
  const bodyH = innerH - headLead - gap - (foot ? footLead + gap : 0) - (noteLines ? noteLines * footLead + gap / 2 : 0)
  // The picture's box: a column beside the words, a band above them; no
  // taller than the picture's shape asks, so a wide one (a map, a logo) is
  // shown whole rather than cut to a slice.
  const thumbAspect = e.thumb && e.thumb.w > 0 && e.thumb.h > 0 ? e.thumb.w / e.thumb.h : 1
  const photoW = wide ? Math.round(innerW * 0.36) : innerW
  const photoH = Math.round(Math.min(wide ? bodyH : bodyH * 0.42, photoW / thumbAspect))
  const between = Math.round(wide ? gap * 1.5 : gap)
  // A picture that did not load leaves its room to the words.
  const image = photoOn ? picture(app, e.thumb, photoW, photoH) : null
  const textW = image && wide ? innerW - photoW - between : innerW
  const textH = image && !wide ? bodyH - photoH - gap : bodyH
  const text = image ? e.text : unpictured(e.text)
  const year = Math.round(Math.min(yearSize, textH * 0.3))
  const yearH = Math.round(year * 1.02)
  const agoH = Math.round(agoSize * 1.4)
  const room = textH - yearH - agoH - Math.round(gap * 0.75)
  const sizes = [40, 36, 34, 32, 30, 28, 26, 24, 22, 20, 19, 18, 17, 16, 15, 14].map((s) => Math.max(13, Math.round(s * u)))

  // "A few": the next events under this one, a line or two each, as many as
  // leave this one in large type (at least 22 px at an 800x480 panel's size).
  const rowSize = Math.max(13, Math.round(16 * u))
  const rowLead = Math.round(rowSize * 1.3)
  const rowYear = Math.round(rowSize * 4.2)
  const rows: { e: any; lines: number }[] = []
  let rowsH = 0
  if (String(app.state.count || 'one') === 'few' && n > 1) {
    for (let k = 1; k < Math.min(n, 4); k++) {
      const next = day.events[(index + k) % n]
      const lines = Math.min(2, Math.max(1, Math.round(frameos.measureText([unpictured(next.text)], { className: `text-[${rowSize}px] leading-[${rowLead}px]`, width: textW - rowYear })[0] / rowLead)))
      const h = lines * rowLead + gap
      const left = fitting(text, textW, room - rowsH - h - gap, sizes.filter((s) => s >= Math.round(22 * u)))
      if (!left.fits) break
      rows.push({ e: next, lines })
      rowsH += h
    }
    if (rows.length) rowsH += gap
  }
  const body = fitting(text, textW, room - rowsH, rows.length ? sizes.filter((s) => s >= Math.round(22 * u)) : sizes)
  const photo = image ? (
    <div className={`w-[${photoW}px] h-[${photoH}px] shrink-0 ${t.photo}`}>
      <img className={`w-[${photoW}px] h-[${photoH}px] object-cover`} src={image} />
    </div>
  ) : null
  const column = (
    <div className={`flex flex-col w-[${textW}px] h-[${textH}px]`}>
      <div className={`font-[Cormorant_Garamond] font-bold text-[${year}px] leading-[${yearH}px] ${t.accent}`}>{yearWords(day.lang, e.year)}</div>
      <div className={`text-[${agoSize}px] leading-[${agoH}px] ${t.soft}`}>{agoWords(day.lang, e.year, new Date(now))}</div>
      <div className={`mt-[${Math.round(gap * 0.75)}px] text-[${body.size}px] leading-[${body.lead}px] line-clamp-${body.lines}`}>{text}</div>
      {rows.length ? <div className="flex-1" /> : null}
      {rows.length ? <div className={`h-[${Math.max(1, Math.round(2 * u))}px] mb-[${gap}px] ${t.rule}`} /> : null}
      {rows.map((row) => (
        <div className={`flex flex-row mb-[${gap}px] text-[${rowSize}px] leading-[${rowLead}px]`}>
          <div className={`w-[${rowYear}px] shrink-0 font-bold ${t.accent}`}>{yearWords(day.lang, row.e.year)}</div>
          <div className={`flex-1 min-w-0 line-clamp-${row.lines}`}>{unpictured(row.e.text)}</div>
        </div>
      ))}
    </div>
  )
  return (
    <div className={`flex flex-col w-[${W}px] h-[${H}px] p-[${pad}px] ${t.page}`} onClick={toNext} onSwipe={swiped}>
      <div className={`flex items-center justify-between h-[${headLead}px] text-[${head}px] leading-[${headLead}px]`}>
        <span className={`uppercase font-bold truncate ${t.accent}`}>{header}</span>
        <span className={`shrink-0 ml-[${gap}px] ${t.soft}`}>{counter}</span>
      </div>
      {note ? <div className={`mt-[${Math.round(gap / 2)}px] px-[${Math.round(8 * u)}px] text-[${foot}px] leading-[${footLead}px] line-clamp-2 ${t.note}`}>{note}</div> : null}
      <div className={`flex ${wide ? 'flex-row' : 'flex-col'} mt-[${gap}px] h-[${bodyH}px] gap-[${between}px]`}>
        {wide ? column : photo}
        {wide ? photo : column}
      </div>
      <div className={`mt-[${gap}px] h-[${footLead}px] text-[${foot}px] leading-[${footLead}px] ${t.soft}`}>{`${day.lang || lang}.wikipedia.org`}</div>
    </div>
  )
}

sources.otd.ts:
// The day's events from Wikipedia's "On this day" feed, and the words the
// scene says in each of its languages.
//
// The feed's "selected" events are the ones a language's Wikipedia shows on
// its main page: five to twenty a day, from 35 KB (German) to 170 KB
// (English) of JSON, read once a day. Only what the scene shows is kept:
// each event's year, its text and its picture's small thumbnail.

// A thumbnail: its address and size, and the width of the picture it is made from.
export type Thumb = { src: string; w: number; h: number; ow: number }
export type Happening = { year: number; text: string; thumb: Thumb | null }

export const LANGUAGES = ['en', 'de', 'fr', 'es', 'it', 'pt', 'sv', 'ru']

// Wikipedia's API asks every client to say who it is: a User-Agent with a
// way to reach its makers (Api-User-Agent where a browser keeps its own).
const UA = 'FrameOS On this day (https://github.com/FrameOS/frameos)'
export const HEADERS = { 'User-Agent': UA, 'Api-User-Agent': UA, Accept: 'application/json' }

// At most this many events of a day are kept (a language without selected
// events gives all of the day's instead, a hundred or more).
const MOST = 24

const pad = (n: number) => String(n).padStart(2, '0')

/** "2026-11-28" for a moment, in the frame's time zone. */
export const dayOf = (d: Date) => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`

// An event's text as it reads on a frame: soft hyphens and doubled spaces
// gone, a capital letter in front (the French and Russian feeds start in
// lower case).
function tidy(text: string): string {
  const t = String(text || '').replace(/­/g, '').replace(/\s+/g, ' ').trim()
  return t ? t[0].toUpperCase() + t.slice(1) : ''
}

/** The events of a feed answer, newest first as the feed has them. */
export function fromFeed(json: any): Happening[] {
  const list = Array.isArray(json?.selected) && json.selected.length ? json.selected : Array.isArray(json?.events) ? json.events : []
  const all: Happening[] = []
  for (const e of list) {
    const year = Number(e?.year)
    const text = tidy(e?.text)
    if (!Number.isFinite(year) || !text) continue
    const page = (Array.isArray(e.pages) ? e.pages : []).find((p: any) => p && p.thumbnail && typeof p.thumbnail.source === 'string')
    const t = page ? page.thumbnail : null
    all.push({
      year,
      text,
      // The thumbnail as the feed gives it (330 px wide), its tracking query left off.
      thumb: t
        ? { src: String(t.source).split('?')[0], w: Number(t.width) || 0, h: Number(t.height) || 0, ow: Number(page.originalimage?.width) || 0 }
        : null,
    })
  }
  if (all.length <= MOST) return all
  // A long list: as many as are kept, spread over it.
  return Array.from({ length: MOST }, (_, i) => all[Math.floor((i * all.length) / MOST)])
}

/** The day's events in a language, or an error that says why there are none. */
export function fetchDay(lang: string, date: string, embedded: boolean): Happening[] {
  const [, mm, dd] = date.split('-')
  const base = `https://${lang}.wikipedia.org/api/rest_v1/feed/onthisday`
  const get = (kind: string) => {
    const r = frameos.httpRequest(`${base}/${kind}/${mm}/${dd}`, { headers: HEADERS, timeoutMs: 30000 })
    if (!r.status) throw new Error(`Wikipedia did not answer${r.error ? `: ${r.error}` : ''}`)
    if (r.status === 429) throw new Error('Wikipedia says too many requests')
    if (r.status === 404) throw new Error(`${lang}.wikipedia.org has no "on this day" feed`)
    if (r.status >= 400) throw new Error(`Wikipedia answered HTTP ${r.status}`)
    try {
      return JSON.parse(r.body || '')
    } catch (e) {
      throw new Error('Wikipedia sent something that is not JSON')
    }
  }
  let events = fromFeed(get('selected'))
  // Some days a language picks none (Spanish, often): all of the day's
  // events instead, which is too much JSON for an ESP32.
  if (events.length === 0 && !embedded) events = fromFeed(get('events'))
  if (events.length === 0) throw new Error(`${lang}.wikipedia.org picked no events for this day`)
  return events
}

// ------------------------------------------------------------ words

type Words = {
  title: string
  months: string[]
  date: (day: number, month: string) => string
  ago: (n: number) => string
  thisYear: string
  bc: string
}

const plural = (n: number, one: string, many: string) => (n === 1 ? one : many)

export const WORDS: Record<string, Words> = {
  en: {
    title: 'On this day',
    months: ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'],
    date: (d, m) => `${m} ${d}`,
    ago: (n) => `${n} ${plural(n, 'year', 'years')} ago`,
    thisYear: 'This year',
    bc: 'BC',
  },
  de: {
    title: 'An diesem Tag',
    months: ['Januar', 'Februar', 'März', 'April', 'Mai', 'Juni', 'Juli', 'August', 'September', 'Oktober', 'November', 'Dezember'],
    date: (d, m) => `${d}. ${m}`,
    ago: (n) => `vor ${n} ${plural(n, 'Jahr', 'Jahren')}`,
    thisYear: 'Dieses Jahr',
    bc: 'v. Chr.',
  },
  fr: {
    title: 'Ce jour-là',
    months: ['janvier', 'février', 'mars', 'avril', 'mai', 'juin', 'juillet', 'août', 'septembre', 'octobre', 'novembre', 'décembre'],
    date: (d, m) => `${d === 1 ? '1er' : d} ${m}`,
    ago: (n) => `il y a ${n} ${plural(n, 'an', 'ans')}`,
    thisYear: 'Cette année',
    bc: 'av. J.-C.',
  },
  es: {
    title: 'Un día como hoy',
    months: ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'],
    date: (d, m) => `${d} de ${m}`,
    ago: (n) => `hace ${n} ${plural(n, 'año', 'años')}`,
    thisYear: 'Este año',
    bc: 'a. C.',
  },
  it: {
    title: 'Accadde oggi',
    months: ['gennaio', 'febbraio', 'marzo', 'aprile', 'maggio', 'giugno', 'luglio', 'agosto', 'settembre', 'ottobre', 'novembre', 'dicembre'],
    date: (d, m) => `${d === 1 ? '1º' : d} ${m}`,
    ago: (n) => `${n} ${plural(n, 'anno', 'anni')} fa`,
    thisYear: "Quest'anno",
    bc: 'a.C.',
  },
  pt: {
    title: 'Neste dia',
    months: ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'],
    date: (d, m) => `${d} de ${m}`,
    ago: (n) => `há ${n} ${plural(n, 'ano', 'anos')}`,
    thisYear: 'Este ano',
    bc: 'a.C.',
  },
  sv: {
    title: 'Denna dag',
    months: ['januari', 'februari', 'mars', 'april', 'maj', 'juni', 'juli', 'augusti', 'september', 'oktober', 'november', 'december'],
    date: (d, m) => `${d} ${m}`,
    ago: (n) => `för ${n} år sedan`,
    thisYear: 'I år',
    bc: 'f.Kr.',
  },
  ru: {
    title: 'В этот день',
    months: ['января', 'февраля', 'марта', 'апреля', 'мая', 'июня', 'июля', 'августа', 'сентября', 'октября', 'ноября', 'декабря'],
    date: (d, m) => `${d} ${m}`,
    ago: (n) => {
      const ten = n % 10
      const hundred = n % 100
      const word = ten === 1 && hundred !== 11 ? 'год' : ten >= 2 && ten <= 4 && (hundred < 12 || hundred > 14) ? 'года' : 'лет'
      return `${n} ${word} назад`
    },
    thisYear: 'В этом году',
    bc: 'до н. э.',
  },
}

export const wordsFor = (lang: string) => WORDS[lang] || WORDS.en

/** "November 28" in the language. */
export const dateWords = (lang: string, date: string) => {
  const w = wordsFor(lang)
  const [, mm, dd] = date.split('-')
  return w.date(Number(dd), w.months[Number(mm) - 1] || '')
}

/** The year as it is written: "1443", or "44 BC". */
export const yearWords = (lang: string, year: number) => (year < 0 ? `${-year} ${wordsFor(lang).bc}` : String(year))

/** "10 years ago" from this year; there is no year 0 between 1 BC and AD 1. */
export function agoWords(lang: string, year: number, now: Date): string {
  const n = now.getFullYear() - year - (year < 0 ? 1 : 0)
  return n <= 0 ? wordsFor(lang).thisYear : wordsFor(lang).ago(n)
}

