import { get, onEvent, readDay, thumbUrl } from './app'
import { agoWords, dateWords, fromFeed, yearWords } from './otd'

// Wikipedia's "On this day" feed as it answers (/feed/onthisday/selected/11/28),
// each page cut to the fields the scene reads, as it was on 2026-11-28.
const page = (title: string, thumb?: [string, number, number, number]) => ({
  type: 'standard',
  title,
  namespace: { id: 0, text: '' },
  titles: { canonical: title, normalized: title.replace(/_/g, ' ') },
  ...(thumb
    ? {
        thumbnail: { source: `${thumb[0]}?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail`, width: thumb[1], height: thumb[2] },
        originalimage: { source: 'https://upload.wikimedia.org/x.jpg', width: thumb[3], height: thumb[3] },
      }
    : {}),
  extract: 'A long extract the scene never shows.',
})
const LAMIA = 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8c/Rescate_2933.jpg/330px-Rescate_2933.jpg'
const FEED = {
  selected: [
    { text: 'LaMia Flight 2933 crashed near Medellín, Colombia, killing 71 people.', pages: [page('LaMia_Flight_2933', [LAMIA, 330, 346, 551]), page('Chapecoense')], year: 2016 },
    { text: 'Tropical Storm Zelda struck the Marshall Islands, leaving 6,000 residents homeless.', pages: [page('Tropical_Storm_Zelda')], year: 1991 },
    { text: 'Wasfi Tal (pictured), Prime Minister of Jordan, was assassinated in Cairo.', pages: [page('Wasfi_Tal', ['https://upload.wikimedia.org/wikipedia/commons/5/58/Wasfi_Al-Tal_cropped.png', 195, 272, 195])], year: 1971 },
  ],
}

// Saturday 28 November 2026, 15:00 in the zone the test runs in.
const NOW = new Date(2026, 10, 28, 15, 0, 0).getTime()
const HOUR = 3600 * 1000

function at<T>(when: number, run: () => T): T {
  const real = Date.now
  Date.now = () => when
  try {
    return run()
  } finally {
    Date.now = real
  }
}

// Every text a UI draws, function components run, in order.
function texts(node: any): string[] {
  if (node === null || node === undefined || node === false || node === true) return []
  if (typeof node === 'string' || typeof node === 'number') return [String(node)]
  if (Array.isArray(node)) return node.flatMap(texts)
  if (typeof node.type === 'function') return texts(node.type(node.props || {}))
  return texts(node.props?.children)
}
const shown = (node: any) => texts(node).join(' ')
function find(node: any, test: (n: any) => boolean): any {
  if (!node || typeof node !== 'object') return null
  if (Array.isArray(node)) {
    for (const child of node) {
      const hit = find(child, test)
      if (hit) return hit
    }
    return null
  }
  if (typeof node.type === 'function') return find(node.type(node.props || {}), test)
  if (test(node)) return node
  return find(node.props?.children, test)
}

function wikipedia(answer: (url: string, options: any) => any) {
  return mock.httpRequest((url: string, options: any) => answer(url, options))
}

describe('the feed', () => {
  it('keeps each event’s year, text and thumbnail, without the tracking query', () => {
    const events = fromFeed(FEED)
    expect(events.length).toBe(3)
    expect(events[0]).toEqual({
      year: 2016,
      text: 'LaMia Flight 2933 crashed near Medellín, Colombia, killing 71 people.',
      thumb: { src: LAMIA, w: 330, h: 346, ow: 551 },
    })
    expect(events[1].thumb).toBe(null)
  })

  it('tidies a text: soft hyphens out, a capital letter in front', () => {
    const events = fromFeed({ selected: [{ text: 'l’écrasement du vol Air New Zealand 901', pages: [], year: 1979 }, { text: 'Der Taroko-National­park', pages: [], year: 1986 }, { text: 'no year', pages: [] }] })
    expect(events.map((e) => e.text)).toEqual(['L’écrasement du vol Air New Zealand 901', 'Der Taroko-Nationalpark'])
  })

  it('keeps 24 of a long list of all the day’s events, spread over it', () => {
    const many = { selected: [], events: Array.from({ length: 72 }, (_, i) => ({ text: `Event ${i}`, pages: [], year: 2000 - i })) }
    const kept = fromFeed(many)
    expect(kept.length).toBe(24)
    expect(kept[0].text).toBe('Event 0')
    expect(kept[1].text).toBe('Event 3')
  })
})

describe('the words', () => {
  it('says the date and how long ago in each language', () => {
    const now = new Date(NOW)
    expect(dateWords('en', '2026-11-28')).toBe('November 28')
    expect(dateWords('de', '2026-11-28')).toBe('28. November')
    expect(dateWords('fr', '2026-12-01')).toBe('1er décembre')
    expect(dateWords('ru', '2026-11-28')).toBe('28 ноября')
    expect(agoWords('en', 2016, now)).toBe('10 years ago')
    expect(agoWords('en', 2025, now)).toBe('1 year ago')
    expect(agoWords('en', 2026, now)).toBe('This year')
    expect(agoWords('de', 1986, now)).toBe('vor 40 Jahren')
    expect(agoWords('ru', 2000, now)).toBe('26 лет назад')
    expect(agoWords('ru', 2025, now)).toBe('1 год назад')
    expect(agoWords('ru', 2003, now)).toBe('23 года назад')
    expect(agoWords('ru', 2015, now)).toBe('11 лет назад')
  })

  it('writes a year before Christ, with no year 0 in the count', () => {
    expect(yearWords('en', -44)).toBe('44 BC')
    expect(yearWords('fr', -44)).toBe('44 av. J.-C.')
    expect(agoWords('en', -44, new Date(NOW))).toBe('2069 years ago')
  })
})

describe('the picture', () => {
  it('asks for a thumbnail width Wikipedia makes, never wider than the picture', () => {
    const thumb = { src: LAMIA, w: 330, h: 346, ow: 551 }
    expect(thumbUrl(thumb, 280)).toBe(LAMIA)
    expect(thumbUrl(thumb, 480)).toBe(LAMIA.replace('/330px-', '/500px-'))
    // 960 would be wider than the 551 px picture.
    expect(thumbUrl(thumb, 1000)).toBe(LAMIA.replace('/330px-', '/500px-'))
    expect(thumbUrl({ ...thumb, ow: 2000 }, 1000)).toBe(LAMIA.replace('/330px-', '/960px-'))
    // A picture that is its own thumbnail stays as it is.
    const small = { src: 'https://upload.wikimedia.org/wikipedia/commons/5/58/Wasfi_Al-Tal_cropped.png', w: 195, h: 272, ow: 195 }
    expect(thumbUrl(small, 400)).toBe(small.src)
  })
})

describe('the scene', () => {
  it('fetches the day’s events once, saying who it is, and shows the first with its picture', () => {
    const http = wikipedia(() => mock.json(FEED))
    const fetchImage = mock.fetchImage(() => mock.image({ width: 252, height: 344 }))
    mock.releaseImage(() => true)
    const app = makeApp({ state: {} })
    const ui = at(NOW, () => get(app, makeContext()))
    expect(http.calls.length).toBe(1)
    expect(http.calls[0][0]).toBe('https://en.wikipedia.org/api/rest_v1/feed/onthisday/selected/11/28')
    expect(http.calls[0][1].headers['User-Agent']).toContain('FrameOS')
    expect(http.calls[0][1].headers['Api-User-Agent']).toContain('FrameOS')
    expect(fetchImage.calls[0][0]).toBe(LAMIA)
    expect(fetchImage.calls[0][1]).toMatchObject({ keep: true })
    const words = shown(ui)
    expect(words).toContain('On this day · November 28')
    expect(words).toContain('2016')
    expect(words).toContain('10 years ago')
    expect(words).toContain('LaMia Flight 2933 crashed')
    expect(words).toContain('1 / 3')
    expect(readDay(app.state.onThisDay)).toMatchObject({ key: 'en:2026-11-28', index: 0, shownAt: NOW, error: '' })
    // Within the hour (a tap, a layout's clock) nothing is fetched and nothing moves on.
    at(NOW + 10 * 60 * 1000, () => get(app, makeContext()))
    expect(http.calls.length).toBe(1)
    expect(readDay(app.state.onThisDay).index).toBe(0)
  })

  it('shows the next event each hour, round and round, and starts over the next day', () => {
    const http = wikipedia(() => mock.json(FEED))
    mock.fetchImage(() => mock.image())
    mock.releaseImage(() => true)
    const app = makeApp({ state: {} })
    at(NOW, () => get(app, makeContext()))
    const second = shown(at(NOW + HOUR, () => get(app, makeContext())))
    expect(second).toContain('Tropical Storm Zelda')
    expect(second).toContain('2 / 3')
    at(NOW + 2 * HOUR, () => get(app, makeContext()))
    // Without its picture, "(pictured)" points at nothing.
    const plain = makeApp({ state: { ...app.state, pictures: 'false' } })
    expect(shown(at(NOW + 2 * HOUR + 1000, () => get(plain, makeContext())))).toContain('Wasfi Tal, Prime Minister of Jordan')
    useApp(app)
    expect(shown(at(NOW + 3 * HOUR, () => get(app, makeContext())))).toContain('1 / 3')
    // At 23:30 the frame wakes for midnight, not an hour later.
    at(new Date(2026, 10, 28, 23, 30, 0).getTime(), () => get(app, makeContext()))
    expect(app.nextSleep).toBe(1805)
    at(new Date(2026, 10, 29, 0, 0, 5).getTime(), () => get(app, makeContext()))
    expect(http.calls.length).toBe(2)
    expect(http.calls[1][0]).toBe('https://en.wikipedia.org/api/rest_v1/feed/onthisday/selected/11/29')
    expect(readDay(app.state.onThisDay)).toMatchObject({ key: 'en:2026-11-29', index: 0 })
  })

  it('moves on and back with a tap, the frame’s keys and a keyboard’s arrows', () => {
    wikipedia(() => mock.json(FEED))
    mock.fetchImage(() => mock.image())
    mock.releaseImage(() => true)
    const app = makeApp({ state: {} })
    const ui = at(NOW, () => get(app, makeContext()))
    const card = find(ui, (n) => typeof n.props?.onClick === 'function')
    at(NOW + 1000, () => card.props.onClick({ type: 'tap', x: 10, y: 10, localX: 10, localY: 10 }))
    expect(readDay(app.state.onThisDay).index).toBe(1)
    // The render after the tap shows it and does not move on again.
    expect(shown(at(NOW + 2000, () => get(app, makeContext())))).toContain('2 / 3')
    expect(onEvent(app, makeContext({ event: 'forward', payload: {} }))).toBe(true)
    expect(readDay(app.state.onThisDay).index).toBe(2)
    expect(onEvent(app, makeContext({ event: 'back', payload: {} }))).toBe(true)
    expect(onEvent(app, makeContext({ event: 'keyDown', payload: { key: 'ArrowLeft' } }))).toBe(true)
    expect(readDay(app.state.onThisDay).index).toBe(0)
    expect(onEvent(app, makeContext({ event: 'keyDown', payload: { key: 'ArrowLeft' } }))).toBe(true)
    expect(readDay(app.state.onThisDay).index).toBe(2)
    expect(onEvent(app, makeContext({ event: 'keyDown', payload: { key: 'a' } }))).toBe(false)
  })

  it('draws no picture in black and white, and asks for none', () => {
    wikipedia(() => mock.json(FEED))
    const fetchImage = mock.fetchImage(() => mock.image())
    const app = makeApp({ state: {}, frame: { color: false, paper: true } })
    const ui = at(NOW, () => get(app, makeContext()))
    expect(fetchImage.calls.length).toBe(0)
    expect(find(ui, (n) => n.type === 'img')).toBe(null)
  })

  it('says why when there are no events, and waits half an hour before asking again', () => {
    const http = wikipedia(() => mock.response(429, 'You are making too many requests to the API.'))
    const app = makeApp({ state: {} })
    const words = shown(at(NOW, () => get(app, makeContext())))
    expect(words).toContain('Could not get the day\'s events: Wikipedia says too many requests.')
    expect(words).toContain('Trying again in half an hour.')
    expect(app.nextSleep).toBe(1800)
    at(NOW + 10 * 60 * 1000, () => get(app, makeContext()))
    expect(http.calls.length).toBe(1)
    at(NOW + 31 * 60 * 1000, () => get(app, makeContext()))
    expect(http.calls.length).toBe(2)
  })

  it('keeps showing yesterday’s events, saying so, when today’s do not come', () => {
    wikipedia(() => ({ status: 0, error: 'connection timed out' }))
    mock.fetchImage(() => mock.image())
    mock.releaseImage(() => true)
    const yesterday = { key: 'en:2026-11-27', date: '2026-11-27', lang: 'en', events: fromFeed(FEED), index: 1, shownAt: NOW - 2 * HOUR, lookedAt: 0, lookedKey: '', error: '' }
    const app = makeApp({ state: { onThisDay: yesterday } })
    const words = shown(at(NOW, () => get(app, makeContext())))
    expect(words).toContain("Could not get today's events: Wikipedia did not answer: connection timed out. These are from November 27.")
    expect(words).toContain('On this day · November 27')
    expect(readDay(app.state.onThisDay)).toMatchObject({ key: 'en:2026-11-27', lookedKey: 'en:2026-11-28', index: 2 })
  })

  it('takes all of the day’s events where a language picked none, except on an ESP32', () => {
    const http = wikipedia((url) =>
      url.includes('/selected/') ? mock.json({ selected: [] }) : mock.json({ events: [{ text: 'fallece Silvia Pinal', pages: [], year: 2024 }] }),
    )
    mock.fetchImage(() => mock.image())
    const app = makeApp({ state: { language: 'es' } })
    const words = shown(at(NOW, () => get(app, makeContext())))
    expect(http.calls[1][0]).toBe('https://es.wikipedia.org/api/rest_v1/feed/onthisday/events/11/28')
    expect(words).toContain('Un día como hoy · 28 de noviembre')
    expect(words).toContain('Fallece Silvia Pinal')
    expect(words).toContain('hace 2 años')
    const esp = makeApp({ state: { language: 'es' }, frame: { embedded: true } })
    expect(shown(at(NOW, () => get(esp, makeContext())))).toContain('es.wikipedia.org picked no events for this day')
  })
})
